                  <span className="art:h-2 art:w-3/5 art:rounded-full art:bg-foreground/22"/>
                  <span className="art:h-2 art:w-full art:rounded-full art:bg-foreground/12"/>
                  <span className="art:h-2 art:w-4/5 art:rounded-full art:bg-foreground/12"/>
                </motion.div>
              </div>
              <div className="art:absolute art:top-1/2 art:left-1/2 art:-translate-x-1/2 art:-translate-y-1/2">
                <motion.div key={reduce && embedded ? String(dark) : undefined} className="art:flex art:h-28 art:w-36 art:flex-col art:justify-end art:gap-2 art:rounded-3xl art:border art:border-border/55 art:bg-background/46 art:p-4 art:backdrop-blur-xl" initial={{ opacity: 1, x: 70, y: 10, rotate: reduce ? 0 : 8 }} animate={{ opacity: 1, x: 70, y: active ? [10, 5, 10] : 10, ...(reduce && !reducedRestingPose ? { rotate: embedded && !dark ? 0 : 8 } : { rotate: active ? [8, 6.24, 8] : 8 }) }} transition={active ? { duration: 5.6, ease: ARTEMIS_EASE_IN_OUT, repeat: Infinity, delay: 0.08 } : { duration: 0 }}>
                  <span className="art:h-2 art:w-3/5 art:rounded-full art:bg-foreground/22"/>
                  <span className="art:h-2 art:w-full art:rounded-full art:bg-foreground/12"/>
                  <span className="art:h-2 art:w-4/5 art:rounded-full art:bg-foreground/12"/>
                </motion.div>
              </div>
              <div className="art:absolute art:top-1/2 art:left-1/2 art:-translate-x-1/2 art:-translate-y-1/2">
                <motion.div className="art:grid art:size-24 art:place-items-center art:border art:border-border/60 art:bg-background/72 art:text-foreground art:backdrop-blur-xl art:rounded-full" initial={{ opacity: 1, scale: 1, rotate: 0 }} animate={{ opacity: 1, scale: active ? [1, 1.035, 1, 1.035, 1] : 1, rotate: active ? [0, 2, 0, -2, 0] : 0 }} transition={active ? { duration: 6, ease: ARTEMIS_EASE_IN_OUT, repeat: Infinity } : { duration: 0 }}>
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.55" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-sparkles art:size-8" aria-hidden="true">
                    <path d="M11.017 2.814a1 1 0 0 1 1.966 0l1.051 5.558a2 2 0 0 0 1.594 1.594l5.558 1.051a1 1 0 0 1 0 1.966l-5.558 1.051a2 2 0 0 0-1.594 1.594l-1.051 5.558a1 1 0 0 1-1.966 0l-1.051-5.558a2 2 0 0 0-1.594-1.594l-5.558-1.051a1 1 0 0 1 0-1.966l5.558-1.051a2 2 0 0 0 1.594-1.594z"/>
                    <path d="M20 2v4"/>
                    <path d="M22 4h-4"/>
                    <circle cx="4" cy="20" r="2"/>
                  </svg>
                </motion.div>
              </div>
            </div>
            <motion.button onClick={() => setVisible(false)} whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} type="button" className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-muted-foreground art:hover:bg-primary/5 art:hover:text-foreground art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:absolute art:top-4 art:right-4 art:z-10 art:size-9 art:border art:border-border/55 art:bg-background/58 art:backdrop-blur-xl art:h-9 art:rounded-full" aria-label="Dismiss announcement" tabIndex={0}>
              <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-x art:size-4" aria-hidden="true">
