                    {"connect."}
                  </span>
                  <span className="art:sr-only">
                    {"connect."}
                  </span>
                </span>
              </span>
            </h2>
            <p className="art:mt-4 art:max-w-lg art:text-pretty art:text-muted-foreground art:text-sm art:leading-6" style={{ opacity: "1", filter: "blur(0px)", transform: "none" }}>
              {"Meet a considered collection shaped for teams who want the work to feel clearer, calmer, and more distinctly their own."}
            </p>
            <div className="art:mt-7 art:flex art:flex-col art:gap-2.5 art:@min-[640px]/artemis:flex-row" style={{ opacity: "1", transform: "none" }}>
              <motion.a whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} className="art:inline-flex art:items-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:justify-center art:@min-[640px]/artemis:flex-1 art:h-9 art:rounded-full" href="#" tabIndex={0}>
                {"Explore the release"}
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-right art:size-4" aria-hidden="true">
                  <path d="M5 12h14"/>
                  <path d="m12 5 7 7-7 7"/>
                </svg>
