              <motion.a whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} className="art:inline-flex art:items-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:border art:border-border art:bg-transparent art:text-foreground art:hover:bg-primary/5 art:gap-2 art:px-5 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:justify-center art:@min-[640px]/artemis:flex-1 art:h-9 art:rounded-full" href="#" tabIndex={0}>
                {"Read the story"}
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-up-right art:size-4" aria-hidden="true">
                  <path d="M7 7h10v10"/>
                  <path d="M7 17 17 7"/>
                </svg>
              </motion.a>
            </div>
          </div>
        </motion.aside> : null}
        </AnimatePresence>
      </div>
    </>);
}

"use client";
// @zeus-internal
import { GrainGradient } from "@paper-design/shaders-react";
const COLORS = ["#f8e2c9", "#efb089", "#d88772", "#b8d5ce"];
export function LaunchShader({ reduced, active }: {
    reduced: boolean | null;
    active: boolean;
}) {
    return <GrainGradient className="art:h-full art:w-full" colorBack="#efd6bc" colors={COLORS} softness={0.84} intensity={0.5} noise={0.25} shape="corners" speed={reduced || !active ? 0 : 0.12}/>;
}
